using System;using System.Data;using System.Data.SqlClient;using RetailSales.DAL;using RetailSales.DTO;using System.Collections.Generic;
namespace RetailSales.BUS { public class RetailBUS { RetailDAL d=new RetailDAL(); public DataTable Get(string table){string[] allowed={"SanPham","KhachHang","NhanVien"};if(Array.IndexOf(allowed,table)<0)throw new Exception("Bảng không hợp lệ");return d.Query("SELECT * FROM "+table);} public DataTable Search(string s){return d.SearchProducts(s);} public void Insert(string table,DataRow r){if(table=="SanPham")d.Exec("INSERT SanPham(MaSP,TenSP,GiaBan,SoLuongTon) VALUES(@a,@b,@c,@d)",P("@a",r["MaSP"]),P("@b",r["TenSP"]),P("@c",r["GiaBan"]),P("@d",r["SoLuongTon"]));else if(table=="KhachHang")d.Exec("INSERT KhachHang(TenKH,DienThoai,DiemTichLuy) VALUES(@a,@b,@c)",P("@a",r["TenKH"]),P("@b",r["DienThoai"]),P("@c",r["DiemTichLuy"]));else d.Exec("INSERT NhanVien(TenNV,SoDienThoai,ChucVu) VALUES(@a,@b,@c)",P("@a",r["TenNV"]),P("@b",r["SoDienThoai"]),P("@c",r["ChucVu"]));} public void Update(string table,DataRow r){if(table=="SanPham")d.Exec("UPDATE SanPham SET TenSP=@b,GiaBan=@c,SoLuongTon=@d WHERE MaSP=@a",P("@a",r["MaSP"]),P("@b",r["TenSP"]),P("@c",r["GiaBan"]),P("@d",r["SoLuongTon"]));else if(table=="KhachHang")d.Exec("UPDATE KhachHang SET TenKH=@b,DienThoai=@c,DiemTichLuy=@d WHERE MaKH=@a",P("@a",r["MaKH"]),P("@b",r["TenKH"]),P("@c",r["DienThoai"]),P("@d",r["DiemTichLuy"]));else d.Exec("UPDATE NhanVien SET TenNV=@b,SoDienThoai=@c,ChucVu=@d WHERE MaNV=@a",P("@a",r["MaNV"]),P("@b",r["TenNV"]),P("@c",r["SoDienThoai"]),P("@d",r["ChucVu"]));} public void Delete(string table,object id){string sql=table=="SanPham"?"DELETE SanPham WHERE MaSP=@id":table=="KhachHang"?"DELETE KhachHang WHERE MaKH=@id":"DELETE NhanVien WHERE MaNV=@id";d.Exec(sql,P("@id",id));} public void Pay(int nv,int? kh,List<CartItem> cart){if(cart.Count==0)throw new Exception("Giỏ hàng đang trống.");d.SaveSale(nv,kh,cart);} public decimal RevenueDay(){return d.Scalar("SELECT ISNULL(SUM(TongTien),0) FROM HoaDon WHERE CAST(NgayLap AS DATE)=CAST(GETDATE() AS DATE)");} public decimal RevenueMonth(){return d.Scalar("SELECT ISNULL(SUM(TongTien),0) FROM HoaDon WHERE YEAR(NgayLap)=YEAR(GETDATE()) AND MONTH(NgayLap)=MONTH(GETDATE())");} public DataTable Top5(){return d.Query("SELECT TOP 5 s.MaSP,s.TenSP,SUM(c.SoLuong) AS SoLuongBan FROM ChiTietHoaDon c JOIN SanPham s ON c.MaSP=s.MaSP GROUP BY s.MaSP,s.TenSP ORDER BY SUM(c.SoLuong) DESC");} SqlParameter P(string n,object v){return new SqlParameter(n,v??DBNull.Value);} } }